INSERT INTO rootcause.detection_steps (vendor_slug, step_type, name, content, expected)
VALUES ('sqlserver', 'query', 'Detect SEC-SQL-AUD-020-RC01 (sqlserver)',
        '{"sql": "SELECT TOP 500 CAST(GETDATE() AS DATETIME) AS event_time, s.login_name AS login_name,\n       DB_NAME(r.database_id) AS database_name, CAST(NULL AS NVARCHAR(128)) AS object_name,\n       CAST(qt.text AS NVARCHAR(MAX)) AS statement\nFROM sys.dm_exec_requests AS r WITH (NOLOCK)\nJOIN sys.dm_exec_sessions AS s WITH (NOLOCK) ON s.session_id = r.session_id\nOUTER APPLY sys.dm_exec_sql_text(r.sql_handle) AS qt\nWHERE s.session_id <> @@SPID AND ISNULL(s.login_name,'''') NOT LIKE ''%dbdome%''\n  AND qt.text IS NOT NULL AND (qt.text LIKE ''%DROP%DATABASE%'' OR qt.text LIKE ''%DROP%SCHEMA%'')\nUNION ALL\nSELECT TOP 500 qs.last_execution_time AS event_time, CAST(NULL AS NVARCHAR(128)) AS login_name,\n       DB_NAME(st.dbid) AS database_name, CAST(NULL AS NVARCHAR(128)) AS object_name,\n       CAST(st.text AS NVARCHAR(MAX)) AS statement\nFROM sys.dm_exec_query_stats AS qs WITH (NOLOCK)\nOUTER APPLY sys.dm_exec_sql_text(qs.sql_handle) AS st\nWHERE qs.last_execution_time >= DATEADD(DAY,-1, GETDATE())\n  AND st.text IS NOT NULL AND st.text NOT LIKE ''%dm_exec_query_stats%''\n  AND (st.text LIKE ''%DROP%DATABASE%'' OR st.text LIKE ''%DROP%SCHEMA%'')"}'::jsonb,
